// stlport
#include "PreRTS.h"
#include "Common/ActionManager.h"
#include "GameLogic/Module/DozerAIUpdate.h"

// ZH privateResumeConstruction and WB11CB900; BFME2 reads its Object
// at +8 and dispatches newTask through DozerAIInterface at +3E4.
void DozerAIUpdate::privateResumeConstruction(Object *obj, CommandSourceType cmdSource)
{
 if (obj == 0) return;
 if (TheActionManager->canResumeConstructionOf(getObject(), obj, cmdSource) == FALSE) return;
 ((DozerAIInterface *)((char *)this + 0x3E4))->newTask(DOZER_TASK_BUILD, obj);
}
